/**
 * Hugo Drip Inbound Check — polls Hugo's inbox for drip pipeline replies.
 *
 * This script is triggered by polsia.toml [[crons]] every 15 minutes
 * Mon-Fri 8AM-6PM AEST. It reads the Polsia company inbox (propopspro@polsia.app)
 * and routes drip-reply emails through the classification pipeline.
 *
 * No in-process scheduler — pure batch logic.
 *
 * CRITICAL: isAutoGenerated() is called BEFORE classifyAndApply().
 * Out-of-office autoresponders are NOT valid replies and will cause infinite loops.
 */

const { Pool } = require('pg');
const https = require('https');
const http = require('http');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DATABASE_URL?.includes('localhost') ? false : { rejectUnauthorized: false },
  max: 2,
});

const { isAutoGenerated } = require('../services/hugo-drip-resend');
const { classifyAndApply } = require('../services/hugo-drip-intent');

// ─── Time guards ───────────────────────────────────────────────────────────────

const AEST_OFFSET_HOURS = 10;

function isAestBusinessHours() {
  const now = new Date();
  const aestHour = (now.getUTCHours() + AEST_OFFSET_HOURS) % 24;
  const aestDay = (now.getUTCDay() + 6) % 7;
  return aestDay >= 0 && aestDay <= 4 && aestHour >= 8 && aestHour <= 18;
}

// ─── Polsia inbox reader ───────────────────────────────────────────────────────

async function fetchInboxEmails() {
  const apiKey = process.env.POLSIA_API_KEY || process.env.POLSIA_API_TOKEN;
  if (!apiKey) {
    console.warn('[HugoDripInboundCheck] POLSIA_API_KEY not set');
    return [];
  }

  const baseUrl = (process.env.POLSIA_R2_BASE_URL || 'https://polsia.com').replace(/\/$/, '');

  const endpoints = [
    `${baseUrl}/api/proxy/email/inbox`,
    `${baseUrl}/api/email/inbox`,
  ];

  for (const endpoint of endpoints) {
    try {
      const urlObj = new URL(endpoint);
      urlObj.searchParams.set('unread', 'true');
      urlObj.searchParams.set('limit', '20');

      const result = await new Promise((resolve, reject) => {
        const req = (urlObj.protocol === 'https:' ? https : http).request({
          hostname: urlObj.hostname,
          port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
          path: urlObj.pathname + urlObj.search,
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${apiKey}`,
            'Accept': 'application/json',
          },
        }, (res) => {
          let body = '';
          res.on('data', d => (body += d));
          res.on('end', () => resolve({ statusCode: res.statusCode, body }));
        });
        req.on('error', reject);
        req.setTimeout(10000, () => { req.destroy(); reject(new Error('timeout')); });
        req.end();
      });

      if (result.statusCode === 200) {
        const data = JSON.parse(result.body);
        return data.emails || data.messages || data.items || data.data || [];
      }
    } catch (err) {
      console.warn(`[HugoDripInboundCheck] Error at ${endpoint}: ${err.message}`);
    }
  }

  return [];
}

// ─── Dedup ────────────────────────────────────────────────────────────────────

async function isProcessed(messageId) {
  if (!messageId) return false;
  try {
    const r = await pool.query(
      `SELECT 1 FROM hugo_processed_inbox_ids WHERE message_id = $1 LIMIT 1`,
      [messageId]
    );
    return r.rows.length > 0;
  } catch { return false; }
}

async function markProcessed(messageId, reason) {
  if (!messageId) return;
  try {
    await pool.query(
      `INSERT INTO hugo_processed_inbox_ids (message_id, reason, processed_at)
       VALUES ($1, $2, NOW())
       ON CONFLICT (message_id) DO NOTHING`,
      [messageId, reason || 'drip_inbound_check']
    );
  } catch { /* non-fatal */ }
}

// ─── Main process ─────────────────────────────────────────────────────────────

async function processInboundReplies() {
  if (!isAestBusinessHours()) {
    console.log('[HugoDripInboundCheck] Outside AEST business hours — skipping');
    return { processed: 0, skipped: 0 };
  }

  const stats = { processed: 0, skipped_loop: 0, skipped_dedup: 0, skipped_auto: 0, errors: 0 };

  let emails;
  try {
    emails = await fetchInboxEmails();
  } catch (err) {
    console.error('[HugoDripInboundCheck] Fetch error:', err.message);
    return stats;
  }

  if (!emails.length) return stats;

  for (const rawEmail of emails) {
    const messageId = rawEmail.message_id || rawEmail.id || null;
    const fromAddress = rawEmail.from || '';
    const subject = rawEmail.subject || '(no subject)';
    const bodyText = rawEmail.text || rawEmail.body_text || rawEmail.body || '';
    const headers = rawEmail.headers || {};

    try {
      // Dedup
      if (await isProcessed(messageId)) {
        stats.skipped_dedup++;
        continue;
      }

      // Auto-reply filter (CRITICAL — check BEFORE Groq)
      if (isAutoGenerated(headers)) {
        console.log(`[HugoDripInboundCheck] ⛔ Auto-generated skip: ${fromAddress}`);
        await markProcessed(messageId, 'auto_generated');
        stats.skipped_auto++;
        continue;
      }

      // Find lead by email address (drip leads have drip_status set)
      const leadRows = await pool.query(
        `SELECT id, drip_status, drip_operator_id, name, email, service
         FROM leads
         WHERE email = $1 AND drip_status IS NOT NULL
         ORDER BY created_at DESC LIMIT 1`,
        [fromAddress]
      );

      if (!leadRows.rows[0]) {
        // Not a drip lead — skip
        await markProcessed(messageId, 'not_drip_lead');
        stats.skipped++;
        continue;
      }

      const lead = leadRows.rows[0];
      console.log(`[HugoDripInboundCheck] Drip reply from lead ${lead.id}: "${subject}"`);

      // Classify intent
      await classifyAndApply(bodyText, lead.id, {
        operatorId: lead.drip_operator_id,
        leadName: lead.name,
        jobType: lead.service,
      });

      await markProcessed(messageId, 'drip_classified');
      stats.processed++;

    } catch (err) {
      console.error(`[HugoDripInboundCheck] Error processing "${subject}" from ${fromAddress}:`, err.message);
      await markProcessed(messageId, `error:${err.message.slice(0, 80)}`);
      stats.errors++;
    }
  }

  console.log(`[HugoDripInboundCheck] Done — processed=${stats.processed} auto_skip=${stats.skipped_auto} errors=${stats.errors}`);
  return stats;
}

// ─── CLI entry point ───────────────────────────────────────────────────────────

if (require.main === module) {
  (async () => {
    try {
      console.log('[HugoDripInboundCheck] Starting inbound reply check...');
      const result = await processInboundReplies();
      console.log('[HugoDripInboundCheck] Result:', JSON.stringify(result));
      process.exit(0);
    } catch (err) {
      console.error('[HugoDripInboundCheck] Fatal error:', err.message);
      process.exit(1);
    } finally {
      await pool.end().catch(() => {});
    }
  })();
}

module.exports = { processInboundReplies };